import re

def longest_palindrome(s: str) -> str:
    if not s:
        return ''

    # Check for palindromes of even length
    for i in range(len(s)):
        if s[i] == s[-i-1]:
            if i == len(s) - i - 1:
                return s[i]
            continue
        else:
            break

    # Check for palindromes of odd length
    for i in range(len(s)):
        if s[i] == s[-i-1]:
            if i == len(s) - i - 1:
                return s[i]
            continue
        else:
            break

    # If no palindromes found, return an empty string
    return ''
