def merge_intervals(intervals: List[List[int]]) -> List[List[int]]:
    if not intervals:
        return []

    intervals.sort(key=lambda x: x[0])
    merged = []
    start, end = intervals[0]

    for interval in intervals[1:]:
        if interval[0] <= end:
            end = max(end, interval[1])
        else:
            merged.append([start, end])
            start, end = interval
    merged.append([start, end])

    return merged
