import re

def evaluate(expr: str) -> int:
    # Regular expression to match arithmetic expressions
    expr_pattern = re.compile(r'\s*\d+\s*(\+\s*\d+\s*)?(\-\s*\d+\s*)?(\*\s*\d+\s*)?(\//\s*\d+\s*)?')

    def parse_expression(expression):
        # Parse the expression into a list of tokens
        tokens = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                j = i
                while j < len(expression) and expression[j].isdigit():
                    j += 1
                tokens.append(int(expression[i:j]))
                i = j
            elif expression[i] in '+-*/':
                tokens.append(expression[i])
                i += 1
            elif expression[i] == '(':
                tokens.append('(')
                i += 1
            elif expression[i] == ')':
                tokens.append(')')
                i += 1
            else:
                i += 1
        return tokens

    def evaluate_expression(tokens):
        # Evaluate the expression using the Shunting Yard algorithm
        output = []
        operators = []
        for token in tokens:
            if isinstance(token, int):
                output.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()
            elif token in '+-*/':
                while operators and operators[-1] in '+-*/' and (token == '*' and operators[-1] == '/' or token == '/' and operators[-1] == '*'):
                    output.append(operators.pop())
                operators.append(token)
        while operators:
            output.append(operators.pop())
        return output

    def evaluate_expression_to_int(expression):
        # Evaluate the expression to an integer
        tokens = parse_expression(expression)
        return evaluate_expression(tokens)

    # Evaluate the input expression
    return evaluate_expression_to_int(expr)
