import sys

def edit_distance(a: str, b: str) -> int:
    if a == b:
        return 0
    elif len(a) == 0:
        return len(b)
    elif len(b) == 0:
        return len(a)
    else:
        insert_cost = edit_distance(a, b[1:]) + 1
        delete_cost = edit_distance(a[1:], b) + 1
        replace_cost = edit_distance(a[1:-1], b[1:]) + (a[-1] != b[-1])
        return min(insert_cost, delete_cost, replace_cost)
```

