from typing import List
from math import inf

def min_coins(coins: List[int], amount: int) -> int:
    if amount == 0:
        return 0
    if amount < 0:
        return inf

    min_coins_needed = inf
    for coin in coins:
        if coin > amount:
            continue
        subproblem = min_coins(coins, amount - coin)
        if subproblem != inf:
            min_coins_needed = min(min_coins_needed, subproblem + 1)

    return min_coins_needed if min_coins_needed != inf else -1
