from typing import List

def spiral_order(matrix: List[List[int]]) -> List[int]:
    if not matrix:
        return []

    rows, cols = len(matrix), len(matrix[0])
    total_elements = rows * cols
    result = []
    direction = 0  # 0: right, 1: down, 2: left, 3: up

    for _ in range(total_elements):
        result.append(matrix[direction][direction])
        matrix[direction][direction] = float('inf')  # Mark as visited

        if direction == 0:  # Right
            if direction == cols - 1:
                direction = 1  # Down
            else:
                direction += 1
        elif direction == 1:  # Down
            if direction == rows - 1:
                direction = 2  # Left
            else:
                direction += 1
        elif direction == 2:  # Left
            if direction == 0:
                direction = 3  # Up
            else:
                direction -= 1
        elif direction == 3:  # Up
            if direction == 0:
                direction = 1  # Down
            else:
                direction -= 1

    return result
```

