from typing import List, Tuple
from itertools import combinations

def two_sum_indices(nums: List[int], target: int) -> Tuple[int, int] | None:
    """
    Finds two indices of nums whose elements sum to target. Returns the pair (i, j) with i < j and nums[i] + nums[j] == target.
    If multiple pairs exist, returns the one with the smallest j, and among those the smallest i. Returns None if no such pair exists.
    """
    for i, j in combinations(range(len(nums)), 2):
        if nums[i] + nums[j] == target:
            return (i, j)
    return None
```

