import itertools

def n_queens(n: int) -> int:
    """Return the number of ways to place n non-attacking queens on an n x n chessboard."""
    if n < 1 or n > 10:
        raise ValueError("n must be between 1 and 10.")

    def is_attacking(row, col):
        """Check if placing a queen at [row, col] is not allowed."""
        # Check rows, columns, and diagonals
        for i in range(row):
            if board[i][col] == 1 or board[row][i] == 1:
                return True
            if abs(row - i) == abs(col - board[row][i]):
                return True
        return False

    board = [[0] * n for _ in range(n)]
    count = 0
    for row, col in itertools.product(range(n), range(n)):
        if is_attacking(row, col):
            continue
        board[row][col] = 1
        if row == n - 1:
            count += 1
        else:
            for col in range(n):
                if is_attacking(row + 1, col):
                    continue
                board[row + 1][col] = 1
            if board[row + 1][col] == 1:
                count += 1
    return count

