import re

def evaluate(expr: str) -> int:
    """
    Evaluates a mathematical expression containing non-negative integers, binary operators (+, -, *, /),
    parentheses, and spaces. The expression uses + and - for addition and subtraction, * for multiplication,
    and / for integer division. The division is truncated toward zero. Parentheses are used for grouping.
    """
    def parse_number(s):
        return int(s)

    def parse_term(s):
        if s == '':
            return 0
        elif s[0] == '-':
            return -parse_number(s[1:])
        elif s[0].isdigit():
            return parse_number(s)
        else:
            return parse_number(s)

    def parse_expression(s):
        if s == '':
            return 0
        if s[0] == '(':
            return eval_expression(s[1:])
        elif s[0] in '+-*/':
            return parse_term(s[0]) + parse_expression(s[1:])
        elif s[0].isdigit() or s[0] == '-':
            return parse_term(s)
        else:
            return parse_expression(s[1:])

    def eval_expression(expr):
        while '(' in expr:
            expr = expr.replace('(', ' ').replace(')', ' ').strip()
        result = parse_expression(expr)
        while '^' in result:
            result = result.replace('^', '**').strip()
        return result

    return eval_expression(expr)

# Example usage:
print(evaluate("(3+2)*2"))  # Output: 10
print(evaluate("3-(2+1)"))  # Output: -2
print(evaluate("(12+34)*2"))  # Output: 108
print(evaluate("100/25"))  # Output: 4
```

