import re

def evaluate(expr: str) -> int:
    """
    Evaluate a given arithmetic expression containing non-negative integers,
    binary operators (+, -, *, /), parentheses, and spaces.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    operator_stack = []
    number_stack = []

    for char in expr:
        if char.isspace():
            continue
        elif char in precedence:
            if operator_stack and precedence[char] <= precedence[operator_stack[-1]]:
                operator_stack.append(char)
            else:
                while operator_stack and precedence[char] <= precedence[operator_stack[-1]]:
                    num2 = number_stack.pop()
                    num1 = number_stack.pop()
                    operator = operator_stack.pop()
                    if operator == '+':
                        result = num1 + num2
                    elif operator == '-':
                        result = num1 - num2
                    elif operator == '*':
                        result = num1 * num2
                    elif operator == '/':
                        result = num1 // num2  # Integer division
                    number_stack.append(result)
                operator_stack.append(char)
        else:
            number_stack.append(char)

    while operator_stack:
        num2 = number_stack.pop()
        num1 = number_stack.pop()
        operator = operator_stack.pop()
        if operator == '+':
            result = num1 + num2
        elif operator == '-':
            result = num1 - num2
        elif operator == '*':
            result = num1 * num2
        elif operator == '/':
            result = num1 // num2  # Integer division
        number_stack.append(result)

    return number_stack[0]
```

