from itertools import combinations

def two_sum_indices(nums: List[int], target: int) -> Tuple[int, int] | None:
    """
    Finds two indices of numbers in the list whose sum equals the target.
    If multiple pairs are possible, returns the one with the smallest index value.
    If no pair exists, returns None.
    """
    nums_map = {num: index for index, num in enumerate(nums)}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in nums_map and i != nums_map[complement]:
            return (i, nums_map[complement])
    return None
