from collections import OrderedDict

def lru_misses(capacity: int, requests: list[int]) -> int:
    cache = OrderedDict()
    misses = 0

    for req in requests:
        if req in cache:
            cache.move_to_end(req)  # Move to end if hit
            misses += 1
        else:
            if len(cache) == capacity:
                cache.popitem(last=False)  # Evict the least recently used if full
            cache[req] = None  # Update the key and mark as used

    return misses
