import re

def evaluate(expr: str) -> int:
    def parse_number(s):
        while s and s[0].isspace():
            s = s[1:]
        if s and s[0].isdigit():
            return int(s)
        return s

    def parse_expression(expression):
        numbers = []
        start = 0
        while start < len(expression):
            match = re.match(r'\s*(\d+)\s*(\+|\-|\*|\/|\(|\))', expression[start:])
            if match:
                num = parse_number(match.group(1))
                operator = match.group(2)
                start += match.end(1)
                if operator == '+':
                    numbers.append(num)
                elif operator == '-':
                    numbers.append(-num)
                elif operator == '*':
                    numbers[-1] *= num
                elif operator == '/':
                    numbers[-1] = int(numbers[-1] / num)
            else:
                break
            start += match.end(0)
        return sum(numbers)

    return parse_expression(expr.strip())
