import string

def caesar_shift(s: str, k: int) -> str:
    lower_alphabet = string.ascii_lowercase
    upper_alphabet = string.ascii_uppercase

    def shift_char(char, k):
        if char in lower_alphabet:
            return lower_alphabet[(lower_alphabet.index(char) + k) % 26]
        elif char in upper_alphabet:
            return upper_alphabet[(upper_alphabet.index(char) + k) % 26]
        return char

    return ''.join(shift_char(char, k) for char in s)
