To solve this problem, we can use Tarjan's algorithm for finding the topological order of a graph. This algorithm also helps in detecting cycles in the graph. Here's the Python function that implements this:

```python
def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    def build_graph(edges):
        graph = [[] for _ in range(n)]
        indegree = [0] * n
        for u, v in edges:
            graph[u].append(v)
            indegree[v] += 1
        return graph, indegree

    graph, indegree = build_graph(edges)

    low, disc, stack, order, cycle = [-1] * n, [0] * n, [], []

    def explore(u, parent):
        disc[u] = low[u] = len(stack) + 1
        stack.append(u)
        for v in graph[u]:
            if v == parent:
                continue
            if indegree[v] == 0:
                explore(v, u)
                low[u] = min(low[u], low[v])
            elif v not in cycle:
                low[u] = min(low[u], disc[v])
        if low[u] >= disc[u]:
            while True:
                v = stack.pop()
                cycle.append(v)
                if v == u:
                    break
            if u == u:
                cycle.append(u)
            for i in range(len(cycle)):
                if i == 0:
                    order.append(cycle[i])
                else:
                    order.append(cycle[-i])
            return cycle, order, cycle
        return None, order, cycle

    while stack:
        u = stack.pop()
        if u == 0:
            continue
        cycle, order, _ = explore(u, -1)
        if cycle:
            return []
        return order

    return order
```

This function first constructs the graph and initializes the necessary data structures. It then iterates over the nodes in the graph, exploring them and updating the discovery and low values. If a cycle is detected, it returns an empty list. Otherwise, it constructs the topological order and returns it.

