from typing import List
from bisect import bisect_left

def sliding_max(nums: List[int], k: int) -> List[int]:
    if k == 1:
        return nums
    if k == len(nums):
        return [max(nums)] * len(nums)

    max_ = []
    for i in range(len(nums)):
        if len(max_) < k:
            max_.append(nums[i])
        else:
            max_.append(max(max_, nums[i]))

    for i in range(k, len(nums)):
        idx = bisect_left(max_, nums[i])
        if idx < len(max_) and max_[idx] > nums[i]:
            max_[idx] = nums[i]
        else:
            max_.append(nums[i])

    return max_
