    # Regular expression to match arithmetic expressions
    expr_pattern = re.compile(r'\s*(?P<op>\+|-|\*|\/)\s*(?P<left>\d+)\s*(?P=op)\s*(?P<right>\d+)')

    def calculate(left, right, op):
        if op == '+': return left + right
        if op == '-': return left - right
        if op == '*': return left * right
        if op == '/': return left // right  # Integer division

