    frequency = {}

    # Iterate over each character in the string
    for char in s:
        # Check if the character is a lowercase letter
        if char in string.ascii_lowercase:
            # Increment its count in the dictionary
            frequency[char] = frequency.get(char, 0) + 1

    return frequency
