import sys

def edit_distance(a, b):
    if a == b:
        return 0
    elif len(a) > 1 and len(b) > 1:
        distance = 1 + min(
            edit_distance(a[:-1], b),
            edit_distance(a, b[:-1]),
            edit_distance(a[:-1], b[:-1]),
        )
        return distance if distance < len(a) + len(b) else len(a) + len(b)
    else:
        return len(a) + len(b)
```

