from typing import List

def min_coins(coins: List[int], amount: int) -> int:
    if amount == 0:
        return 0
    elif amount < min(coins):
        return -1
    else:
        coins.sort()
        min_coins = 0
        while amount > 0:
            if amount >= coins[0]:
                amount -= coins[0]
                min_coins += 1
            else:
                break
        return min_coins
