import string

def caesar_shift(s: str, k: int) -> str:
    """
    Shifts each ASCII letter in the input string s by k positions in the alphabet, wrapping around the alphabet.
    k can be negative or larger than 26. Non-letter characters are not shifted.
    """
    alphabet = string.ascii_letters  # Include uppercase and lowercase letters
    result = []

    for char in s:
        if char in alphabet:
            shift_amount = k % 26
            if char == char.upper():
                shifted = chr((ord(char) - 65 + shift_amount) % 26 + 65)
            else:
                shifted = chr((ord(char) - 97 + shift_amount) % 26 + 97)
            result.append(shifted)
        else:
            result.append(char)

    return ''.join(result)
```

